from itertools import permutations

k = 0
for p in permutations('кобура'):
    w = ''.join(p)
    for c in 'оуа':
        w = w.replace(c, 'г')
    for c in 'кбр':
        w = w.replace(c, 'с')
    if 'гсгсгс' in w or 'сгсгсг' in w:
        k += 1
print(k)

